package ir.matab.desk;
import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.util.*;
final class ClinicManager{
 final Context context;final SQLiteDatabase registry;final Map<String,LocalDatabase> banks=new HashMap<>();
 ClinicManager(Context context,LocalDatabase primary)throws Exception{this.context=context;registry=context.openOrCreateDatabase("clinics.sqlite3",0,null);registry.execSQL("CREATE TABLE IF NOT EXISTS clinics(id TEXT PRIMARY KEY,name TEXT NOT NULL)");registry.execSQL("INSERT OR IGNORE INTO clinics VALUES(?,?)",new Object[]{"main","مطب من"});banks.put("main",primary);}
 LocalDatabase get(String id)throws Exception{try(Cursor c=registry.rawQuery("SELECT name FROM clinics WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new Exception("مطب انتخاب‌شده وجود ندارد.");}LocalDatabase db=banks.get(id);if(db==null){db=new LocalDatabase(context,"clinic-"+id+".sqlite3");banks.put(id,db);}return db;}
 JSONArray list()throws Exception{JSONArray out=new JSONArray();try(Cursor c=registry.rawQuery("SELECT id,name FROM clinics ORDER BY rowid",null)){while(c.moveToNext()){String id=c.getString(0),name=c.getString(1);JSONObject state=get(id).read().optJSONObject("state");out.put(new JSONObject().put("id",id).put("name",state==null?name:state.getString("clinic")));}}return out;}
 JSONObject backupAll()throws Exception{JSONArray all=list(),out=new JSONArray();for(int i=0;i<all.length();i++){JSONObject c=all.getJSONObject(i);LocalDatabase bank=get(c.getString("id"));JSONObject state=bank.read().optJSONObject("state"),backup=state==null?new JSONObject().put("format","matab-backup").put("formatVersion",1).put("state",JSONObject.NULL).put("history",bank.history(new JSONObject()).getJSONArray("rows")):bank.backup("full");out.put(new JSONObject().put("name",c.getString("name")).put("backup",backup));}return new JSONObject().put("format","matab-all-clinics").put("formatVersion",1).put("clinics",out);}
 JSONObject restoreAll(JSONObject payload)throws Exception{
  if(!payload.getString("format").equals("matab-all-clinics")||payload.getInt("formatVersion")!=1)throw new Exception("پشتیبان کلی معتبر نیست.");JSONArray items=payload.getJSONArray("clinics"),current=list();if(items.length()<1||items.length()+current.length()>100)throw new Exception("تعداد مطب‌ها از سقف مجاز عبور می‌کند.");
  for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i),b=item.getJSONObject("backup");String name=item.getString("name").trim();if(name.isEmpty()||name.length()>80||!b.getString("format").equals("matab-backup")||b.getInt("formatVersion")!=1)throw new Exception("پشتیبان مطب معتبر نیست.");if(!b.isNull("state"))get("main").validate(b.getJSONObject("state"));HistorySupport.validateHistory(b.optJSONArray("history"));}
  Set<String> names=new HashSet<>();for(int i=0;i<current.length();i++)names.add(current.getJSONObject(i).getString("name").toLowerCase(java.util.Locale.ROOT));List<String> staged=new ArrayList<>();List<LocalDatabase> opened=new ArrayList<>();boolean ok=false;registry.beginTransaction();try{
   for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i),b=item.getJSONObject("backup");String base=item.getString("name").trim(),name=base;int n=1;while(names.contains(name.toLowerCase(java.util.Locale.ROOT)))name=base.substring(0,Math.min(55,base.length()))+" (بازیابی "+(n++)+")";names.add(name.toLowerCase(java.util.Locale.ROOT));String key=UUID.randomUUID().toString().replace("-","");staged.add(key);LocalDatabase bank=new LocalDatabase(context,"clinic-"+key+".sqlite3");opened.add(bank);if(!b.isNull("state")){JSONObject state=new JSONObject(b.getJSONObject("state").toString());state.put("clinic",name);bank.write(new JSONObject().put("revision",0).put("operation","restore").put("state",state).put("history",b.optJSONArray("history")));}else bank.getWritableDatabase();registry.execSQL("INSERT INTO clinics VALUES(?,?)",new Object[]{key,name});}
   registry.setTransactionSuccessful();ok=true;return new JSONObject().put("count",items.length()).put("firstId",staged.get(0));
  }finally{registry.endTransaction();for(LocalDatabase bank:opened)bank.close();if(!ok)for(String key:staged)context.deleteDatabase("clinic-"+key+".sqlite3");}
 }
 synchronized void close(){for(LocalDatabase db:banks.values())db.close();registry.close();}
 synchronized JSONObject request(String id,String action,JSONObject p)throws Exception{
  LocalDatabase db=get(id);
  if(action.equals("backupAll"))return backupAll();if(action.equals("restoreAll"))return restoreAll(p);if(action.equals("backupAllEvent")){JSONArray all=list();for(int i=0;i<all.length();i++)get(all.getJSONObject(i).getString("id")).backupEvent("full",p.getString("destination"));return new JSONObject().put("ok",true);}
  if(action.equals("list"))return new JSONObject().put("clinics",list());
  if(action.equals("create")){String name=p.getString("name").trim();if(name.isEmpty()||name.length()>80)throw new Exception("نام مطب باید بین ۱ تا ۸۰ حرف باشد.");JSONArray rows=list();if(rows.length()>=100)throw new Exception("حداکثر ۱۰۰ مطب قابل تعریف است.");for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getString("name").trim().equalsIgnoreCase(name))throw new Exception("مطب هم‌نام وجود دارد.");String key=UUID.randomUUID().toString().replace("-","");registry.execSQL("INSERT INTO clinics VALUES(?,?)",new Object[]{key,name});return new JSONObject().put("id",key).put("name",name);}
  if(action.equals("load"))return db.read();if(action.equals("save"))return db.write(p);if(action.equals("history"))return db.history(p);if(action.equals("releases"))return db.releases();if(action.equals("backup"))return db.backup(p.getString("scope"));if(action.equals("backupEvent")){db.backupEvent(p.getString("scope"),p.getString("destination"));return new JSONObject().put("ok",true);}if(action.equals("info"))return new JSONObject().put("location","SQLite · اطلاعات مستقل مطب انتخاب‌شده");throw new Exception("عملیات مطب معتبر نیست.");
 }
}
